# Arch name = native apt name(s)
#   a b    several packages       a|b   first one that exists
#   -      nothing to install       !   not available here (warns)
# Names that are the same everywhere are not listed.
base-devel     = build-essential
gcc            = gcc g++
dotnet-sdk     = dotnet-sdk-9.0|dotnet-sdk-8.0
typescript     = node-typescript
yarn           = yarnpkg
firefox        = firefox|firefox-esr
chromium       = chromium|chromium-browser
docker         = docker.io
docker-compose = docker-compose-v2|docker-compose
python         = python3
python-pip     = python3-pip
jdk-openjdk    = default-jdk
go             = golang-go
lua            = lua5.4|lua5.3
sqlite         = sqlite3
redis          = redis-server|redis
cursor         = !
